-- Rollback script generated by database-diff on <time>
-- Source (the sync script's model):  <server> / ddtest_core_src
-- Target (will be changed back):     <server> / ddtest_core_tgt
--
-- Running this on the TARGET database after the sync script of the same comparison puts its
-- schema back as it was read during the comparison. REVIEW IT BEFORE RUNNING.
-- - Nothing in this file has been executed by database-diff.
-- - It assumes the target changed only through the sync script since the comparison.
-- - Procedures, views, functions, triggers, synonyms, indexes and constraints the sync script
--   created are dropped first, with IF EXISTS so a sync script that stopped part way is fine.
-- - Tables, columns, sequences, types and schemas it created are commented out at the end:
--   dropping them loses the data written since.
-- - Changed objects get their earlier definition back. ALTER COLUMN statements are active:
--   check them for data loss (narrower types, NOT NULL).
-- - Objects only in the target are not here: the sync script leaves them (its drops are
--   commented out). Schemas it created only when missing are left in place.
-- - Only a backup brings back dropped data.
-- - Objects are ordered by kind, not by dependency; rerun a failed part after the rest.
-- - Uses CREATE OR ALTER and DROP IF EXISTS: SQL Server 2016 SP1 or later on the target.
USE [ddtest_core_tgt];
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

-- ==========================================================================================
-- Created by the sync script: dropped
-- ==========================================================================================
ALTER TABLE [dbo].[Orders] DROP CONSTRAINT IF EXISTS [FK_Orders_Customers];
GO
-- Not scripted: the sync script created Check constraint dbo.Customers (check: (len([Name])>(0))) with a new system-generated name; find it on the target and drop it manually.
ALTER TABLE [dbo].[Orders] DROP CONSTRAINT IF EXISTS [CK_Orders_Amount];
GO
DROP INDEX IF EXISTS [IX_Orders_CreatedAt] ON [dbo].[Orders];
GO
DROP PROCEDURE IF EXISTS [dbo].[pNewOrder];
GO
DROP VIEW IF EXISTS [rpt].[vDailyTotal];
GO
DROP FUNCTION IF EXISTS [dbo].[fOrdersOf];
GO

-- ==========================================================================================
-- Sequences
-- ==========================================================================================
ALTER SEQUENCE [dbo].[seqInvoice] INCREMENT BY 1 MINVALUE -2147483648 MAXVALUE 2147483647 NO CYCLE CACHE;  -- data type and start value are not changed
GO

-- ==========================================================================================
-- Columns
-- ==========================================================================================
-- dbo.Customers.Email: Collation: source SQL_Latin1_General_CP1_CI_AS, target Thai_CI_AS
-- Fails if an index, constraint or schema-bound object uses this column; check for data loss.
ALTER TABLE [dbo].[Customers] ALTER COLUMN [Email] varchar(100) COLLATE Thai_CI_AS NULL;
GO
-- dbo.Orders.Amount: Default: source ((1)), target ((0))
DECLARE @default sysname, @drop nvarchar(max);
SELECT @default = dc.name FROM sys.default_constraints dc JOIN sys.columns c ON c.object_id = dc.parent_object_id AND c.column_id = dc.parent_column_id WHERE dc.parent_object_id = OBJECT_ID(N'[dbo].[Orders]') AND c.name = N'Amount';
IF @default IS NOT NULL BEGIN SET @drop = N'ALTER TABLE [dbo].[Orders] DROP CONSTRAINT ' + QUOTENAME(@default); EXEC (@drop); END
ALTER TABLE [dbo].[Orders] ADD DEFAULT ((0)) FOR [Amount];
GO
-- dbo.Orders.Name: Type: source nvarchar(100), target nvarchar(50) Nullable: source NOT NULL, target NULL
-- Fails if an index, constraint or schema-bound object uses this column; check for data loss.
ALTER TABLE [dbo].[Orders] ALTER COLUMN [Name] nvarchar(50) COLLATE Thai_CI_AS NULL;
GO

